99	function createInviteToken() {
100	  const bytes = randomBytes(INVITE_TOKEN_SUFFIX_LENGTH);
101	  let suffix = "";
102	  for (let idx = 0; idx < INVITE_TOKEN_SUFFIX_LENGTH; idx += 1) {
103	    suffix += INVITE_TOKEN_ALPHABET[bytes[idx]! % INVITE_TOKEN_ALPHABET.length];
104	  }
105	  return `${INVITE_TOKEN_PREFIX}${suffix}`;
