125	function requestBaseUrl(req: Request) {
126	  const forwardedProto = req.header("x-forwarded-proto");
127	  const proto = forwardedProto?.split(",")[0]?.trim() || req.protocol || "http";
128	  const host =
129	    req.header("x-forwarded-host")?.split(",")[0]?.trim() || req.header("host");
130	  if (!host) return "";
131	  return `${proto}://${host}`;
132	}
