142	function readSkillMarkdown(skillName: string): string | null {
143	  const normalized = skillName.trim().toLowerCase();
144	  if (
145	    normalized !== "paperclip" &&
146	    normalized !== "paperclip-create-agent" &&
147	    normalized !== "paperclip-create-plugin" &&
148	    normalized !== "paperclip-converting-plans-to-tasks" &&
149	    normalized !== "para-memory-files"
150	  )
151	    return null;
152	  const moduleDir = path.dirname(fileURLToPath(import.meta.url));
153	  const candidates = [
154	    path.resolve(moduleDir, "../../skills", normalized, "SKILL.md"), // published: dist/routes/ -> <pkg>/skills/
155	    path.resolve(process.cwd(), "skills", normalized, "SKILL.md"), // cwd (e.g. monorepo root)
156	    path.resolve(moduleDir, "../../../skills", normalized, "SKILL.md") // dev: src/routes/ -> repo root/skills/
157	  ];
158	  for (const skillPath of candidates) {
159	    try {
160	      return fs.readFileSync(skillPath, "utf8");
161	    } catch {
162	      // Continue to next candidate.
163	    }
164	  }
165	  return null;
166	}
